-- ---- what this migration claims it did ------------------------------
-- ASSERT: SELECT count(*) FROM translations WHERE namespace = 'tracker' AND key LIKE 'auth.%' = 268
-- ASSERT: SELECT count(*) FROM translations WHERE namespace = 'tracker' AND key LIKE 'auth.%' AND lang = 'en' = 67
-- ASSERT: SELECT count(*) FROM translations WHERE namespace = 'tracker' AND key LIKE 'auth.%' AND lang = 'es' = 67
-- ASSERT: SELECT count(*) FROM translations WHERE namespace = 'tracker' AND key LIKE 'auth.%' AND lang = 'de' = 67
-- ASSERT: SELECT count(*) FROM translations WHERE namespace = 'tracker' AND key LIKE 'auth.%' AND lang = 'fr' = 67

-- ---- and they stay in step -----------------------------------------
--
-- FOUR LANGUAGES OR NONE. The panel has an English fallback behind
-- every string, so a language that is missing rows does not break:
-- it silently serves English inside an otherwise translated page,
-- which is the half-translated render migration 589 exists to
-- prevent and the state this migration is fixing. Stated as an
-- invariant because the failure is invisible.
--
-- ASSERT ALWAYS: SELECT count(DISTINCT lang) FROM translations WHERE namespace = 'tracker' AND key LIKE 'auth.%' = 4
-- ASSERT ALWAYS: SELECT count(*) FROM (SELECT key FROM translations WHERE namespace = 'tracker' AND key LIKE 'auth.%' GROUP BY key HAVING count(DISTINCT lang) <> 4) = 0

-- THE TWO SLOTS SURVIVE TRANSLATION. Both exist because of it: the
-- address used to be glued to the end of an English prefix, which
-- German cannot do, and the attempt count sat between two fragments.
-- A dropped brace loses the value out of the sentence entirely.
--
-- ASSERT ALWAYS: SELECT count(*) FROM translations WHERE namespace = 'tracker' AND key = 'auth.code.lede' AND value LIKE '%{0}%' = 4
-- ASSERT ALWAYS: SELECT count(*) FROM translations WHERE namespace = 'tracker' AND key = 'auth.err.wrongMany' AND value LIKE '%{0}%' = 4
